import {defineComponent,h} from 'vue';
export const YkAIActivity=defineComponent({name:'YkAIActivity',props:{items:{type:Array,default:()=>[]},label:{type:String,default:'任务进展'}},setup(p){const labels={pending:'等待',running:'进行中',success:'完成',error:'失败'};return()=>h('section',{class:'yk-ai-activity','aria-label':p.label},[h('h3',{},p.label),h('ol',{},p.items.map(step=>h('li',{key:step.id,'data-status':step.status},[h('span',{class:'yk-ai-activity__mark','aria-hidden':'true'},step.status==='success'?'✓':step.status==='error'?'!':'·'),h('div',{},[h('strong',{},step.label),step.description?h('p',{},step.description):null]),h('small',{},labels[step.status]||'等待')])))]);}});
